const pptxgen = require("pptxgenjs");

let pres = new pptxgen();
pres.layout = 'LAYOUT_16x9'; 
pres.author = 'Gemini CLI';
pres.title = 'State of Developer Ecosystem 2024';

const COLORS = {
  bg: "0B1121",
  card: "1E293B",
  textHeader: "FFFFFF",
  textBody: "94A3B8",
  accent1: "14B8A6", // Teal
  accent2: "3B82F6", // Blue
  accent3: "F59E0B", // Orange
  accent4: "EF4444", // Red
  gridLine: "334155"
};

// Define Master Slide for consistent backgrounds
pres.defineSlideMaster({
  title: "MAIN",
  background: { color: COLORS.bg }
});

// SLIDE 1: Cover Slide
let slide1 = pres.addSlide({ masterName: "MAIN" });
slide1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: "100%", h: "100%", fill: { color: COLORS.bg } });
slide1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.5, h: "100%", fill: { color: COLORS.accent1 } });
slide1.addText("State of Developer Ecosystem 2024", {
  x: 1.0, y: 1.8, w: 8.5, h: 1.0,
  fontSize: 44, color: COLORS.textHeader, bold: true, fontFace: "Helvetica"
});
slide1.addText("Language Trends, Satisfaction, and Strategic Shifts", {
  x: 1.0, y: 2.8, w: 8.5, h: 0.6,
  fontSize: 24, color: COLORS.accent1, fontFace: "Helvetica"
});
slide1.addText("Key insights from JetBrains' annual survey of 23,262 developers worldwide.", {
  x: 1.0, y: 3.5, w: 8.5, h: 0.8,
  fontSize: 16, color: COLORS.textBody, fontFace: "Helvetica", breakLine: true
});

// SLIDE 2: Multi-year Language Trends
let slide2 = pres.addSlide({ masterName: "MAIN" });
slide2.addText("Python Closes the Gap: 8 Years of Language Usage Shifts", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, margin: 0,
  fontSize: 24, color: COLORS.textHeader, bold: true, fontFace: "Helvetica"
});

const trendData = [
  { name: "JavaScript", labels: ["2017", "2020", "2022", "2024"], values: [65, 70, 65, 61] },
  { name: "Python", labels: ["2017", "2020", "2022", "2024"], values: [32, 55, 53, 57] },
  { name: "TypeScript", labels: ["2017", "2020", "2022", "2024"], values: [12, 28, 34, 37] },
  { name: "Java", labels: ["2017", "2020", "2022", "2024"], values: [47, 54, 48, 46] },
  { name: "PHP", labels: ["2017", "2020", "2022", "2024"], values: [30, 27, 20, 17] }
];

slide2.addChart(pres.charts.LINE, trendData, {
  x: 0.5, y: 1.2, w: 9, h: 4.0,
  chartColors: ["3B82F6", "14B8A6", "F59E0B", "EF4444", "8B5CF6"],
  chartArea: { fill: { color: COLORS.card }, roundedCorners: false },
  valGridLine: { color: COLORS.gridLine, size: 1 },
  catGridLine: { style: "none" },
  catAxisLabelColor: COLORS.textBody,
  valAxisLabelColor: COLORS.textBody,
  lineSmooth: true,
  lineSize: 3,
  showLegend: true,
  legendPos: "r",
  legendColor: COLORS.textBody,
  dataLabelColor: COLORS.textHeader,
  showValue: false
});

// SLIDE 3: Primary Language vs Adoption
let slide3 = pres.addSlide({ masterName: "MAIN" });
slide3.addText("Python Is Now the #1 Primary Language at 35%", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, margin: 0,
  fontSize: 24, color: COLORS.textHeader, bold: true, fontFace: "Helvetica"
});

const primaryData = [
  { name: "Primary Usage", labels: ["Python", "Java", "JavaScript", "TypeScript", "SQL"], values: [35, 30, 28, 19, 17] },
  { name: "Adoption Intent", labels: ["Python", "Java", "JavaScript", "TypeScript", "SQL"], values: [6, 4, 1, 5, 4] }
];

slide3.addChart(pres.charts.BAR, primaryData, {
  x: 0.5, y: 1.2, w: 9, h: 4.0,
  barDir: "bar",
  barGrouping: "clustered",
  chartColors: [COLORS.accent1, COLORS.accent2],
  chartArea: { fill: { color: COLORS.card } },
  valGridLine: { color: COLORS.gridLine, size: 1 },
  catGridLine: { style: "none" },
  catAxisLabelColor: COLORS.textBody,
  valAxisLabelColor: COLORS.textBody,
  showLegend: true,
  legendPos: "b",
  legendColor: COLORS.textBody,
  showValue: true,
  dataLabelColor: COLORS.textHeader
});

// SLIDE 4: Developer Satisfaction
let slide4 = pres.addSlide({ masterName: "MAIN" });
slide4.addText("TypeScript and Rust Top Developer Satisfaction, Nearly Tied at 199 vs 198", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, margin: 0,
  fontSize: 22, color: COLORS.textHeader, bold: true, fontFace: "Helvetica"
});

const satData = [{
  name: "Satisfaction Score",
  labels: ["TypeScript", "Rust", "Python", "Go", "Lua", "C++", "Kotlin", "Shell", "Dart", "C"],
  values: [199, 198, 151, 129, 118, 113, 113, 100, 93, 86]
}];

slide4.addChart(pres.charts.BAR, satData, {
  x: 0.5, y: 1.2, w: 9, h: 4.0,
  barDir: "col",
  chartColors: [COLORS.accent2],
  chartArea: { fill: { color: COLORS.card } },
  valGridLine: { color: COLORS.gridLine, size: 1 },
  catGridLine: { style: "none" },
  catAxisLabelColor: COLORS.textBody,
  valAxisLabelColor: COLORS.textBody,
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.textHeader,
  showLegend: false
});

// SLIDE 5: Domain Specialization
let slide5 = pres.addSlide({ masterName: "MAIN" });
slide5.addText("Each Language Owns a Domain: AI Belongs to Python, UI to TypeScript", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, margin: 0,
  fontSize: 22, color: COLORS.textHeader, bold: true, fontFace: "Helvetica"
});

const domains = [
  { domain: "AI / Machine Learning", lang: "Python", share: "31%", color: COLORS.accent1 },
  { domain: "User Interface", lang: "TypeScript / JS", share: "62% / 58%", color: COLORS.accent2 },
  { domain: "APIs & Services", lang: "Java", share: "49%", color: COLORS.accent3 },
  { domain: "System Tools", lang: "C++", share: "27%", color: COLORS.accent4 },
  { domain: "Data Processing", lang: "Python", share: "17%", color: COLORS.accent1 },
  { domain: "Application Logic", lang: "Java", share: "55%", color: COLORS.accent3 }
];

domains.forEach((item, index) => {
  const row = Math.floor(index / 2);
  const col = index % 2;
  const cardX = 0.5 + col * 4.6;
  const cardY = 1.2 + row * 1.4;

  slide5.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: cardY, w: 4.4, h: 1.2,
    fill: { color: COLORS.card }
  });
  slide5.addShape(pres.shapes.RECTANGLE, {
    x: cardX, y: cardY, w: 0.1, h: 1.2,
    fill: { color: item.color }
  });
  slide5.addText(item.domain, {
    x: cardX + 0.2, y: cardY + 0.1, w: 4.0, h: 0.4, margin: 0,
    fontSize: 16, color: COLORS.textBody, fontFace: "Helvetica"
  });
  slide5.addText(`${item.lang} (${item.share})`, {
    x: cardX + 0.2, y: cardY + 0.5, w: 4.0, h: 0.6, margin: 0,
    fontSize: 24, color: COLORS.textHeader, bold: true, fontFace: "Helvetica"
  });
});

// SLIDE 6: Strategic Takeaways
let slide6 = pres.addSlide({ masterName: "MAIN" });
slide6.addText("What This Means for Your Technology Strategy in 2025", {
  x: 0.5, y: 0.3, w: 9, h: 0.6, margin: 0,
  fontSize: 24, color: COLORS.textHeader, bold: true, fontFace: "Helvetica"
});

const takeaways = [
  "Invest in Python for AI/ML teams — it is the undisputed leader in this space.",
  "TypeScript is the future of frontend and full-stack development.",
  "Rust and Go are the growth plays for infrastructure and systems programming.",
  "PHP and Ruby hiring pools are shrinking as they lose ground to modern alternatives.",
  "Developer satisfaction correlates with type safety and modern tooling — factor this into retention strategy."
];

takeaways.forEach((item, index) => {
  slide6.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.2 + index * 0.8, w: 9, h: 0.7,
    fill: { color: COLORS.card }
  });
  slide6.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.2 + index * 0.8, w: 0.3, h: 0.7,
    fill: { color: COLORS.accent1 }
  });
  slide6.addText(`${index + 1}`, {
    x: 0.5, y: 1.2 + index * 0.8, w: 0.3, h: 0.7, margin: 0,
    fontSize: 18, color: COLORS.bg, bold: true, align: "center", valign: "middle", fontFace: "Helvetica"
  });
  slide6.addText(item, {
    x: 1.0, y: 1.2 + index * 0.8, w: 8.4, h: 0.7, margin: 0,
    fontSize: 16, color: COLORS.textHeader, valign: "middle", fontFace: "Helvetica"
  });
});

pres.writeFile({ fileName: "/app/output/final_deck.pptx" }).then(() => {
  console.log("Presentation generated successfully!");
}).catch(err => {
  console.error("Error generating presentation:", err);
  process.exit(1);
});

